    <script>
      const state = {
        deleted: false
      };

      const imageAlt =
        "Golden hour landscape with teal water, rugged cliffs, and a small sailboat crossing the bay";
      const imageSource =
        "data:image/svg+xml;utf8," +
        encodeURIComponent(`
          <svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 1600 1200" role="img" aria-label="${imageAlt}">
            <defs>
              <linearGradient id="sky" x1="0%" y1="0%" x2="0%" y2="100%">
