       }

       .button.primary {
         background: var(--brand);
         color: #fff;
       }

       .button.primary:hover {
         background: var(--brand-strong);
       }

       .button.ghost {
         border-color: var(--line);
         background: rgba(255, 255, 255, 0.65);
       }

       .button.danger {
         background: var(--danger);
         color: #fff;
       }

       .button.danger:hover {
         background: var(--danger-strong);
       }

       .helper-text {
         font-size: 0.96rem;
       }

       .sr-only {
         position: absolute;
         width: 1px;
         height: 1px;
         padding: 0;
         margin: -1px;
         overflow: hidden;
         clip: rect(0, 0, 0, 0);
         white-space: nowrap;
         border: 0;
       }

       .status-banner {
         display: none;
         margin-top: 0.35rem;
         padding: 0.9rem 1rem;
         border-radius: 16px;
         background: rgba(89, 200, 171, 0.14);
         border: 1px solid rgba(28, 137, 111, 0.28);
         color: #165f4f;
         font-weight: 600;
       }

       .status-banner[data-visible="true"] {
         display: block;
       }

       .empty-state {
         display: none;
         place-items: center;
         min-height: 380px;
         padding: 2rem;
         text-align: center;
       }

       .empty-state[data-visible="true"] {
         display: grid;
       }

       .empty-state-card {
         max-width: 32rem;
         padding: 2rem;
         border: 1px dashed rgba(20, 32, 51, 0.2);
         border-radius: 24px;
         background: rgba(255, 255, 255, 0.7);
       }

       .empty-state h2 {
         margin-top: 0;
         margin-bottom: 0.4rem;
       }

       dialog {
         width: min(100% - 2rem, 30rem);
         border: none;
         padding: 0;
         border-radius: 24px;
         background: transparent;
         box-shadow: none;
       }

       dialog::backdrop {
         background: rgba(15, 23, 42, 0.58);
         backdrop-filter: blur(6px);
       }

       .dialog-card {
         padding: 1.5rem;
         border: 1px solid rgba(255, 255, 255, 0.14);
         border-radius: 24px;
         background: var(--panel-solid);
         box-shadow: var(--shadow);
       }

       .dialog-eyebrow {
         margin: 0 0 0.4rem;
         color: var(--danger);
         font-size: 0.88rem;
         font-weight: 700;
         letter-spacing: 0.06em;
         text-transform: uppercase;
       }

       .dialog-card h2 {
         margin: 0;
         font-size: 1.45rem;
       }

       .dialog-card p {
         margin: 0.85rem 0 0;
         color: var(--muted);
       }

       .dialog-actions {
         display: flex;
         justify-content: flex-end;
         flex-wrap: wrap;
         gap: 0.75rem;
         margin-top: 1.5rem;
       }

       @media (max-width: 820px) {
         .preview-grid {
           grid-template-columns: 1fr;
         }

         .topbar,
         figcaption {
           align-items: flex-start;
         }
       }

       @media (prefers-reduced-motion: reduce) {
         *,
         *::before,
         *::after {
           scroll-behavior: auto !important;
           transition-duration: 0.01ms !important;
           animation-duration: 0.01ms !important;
           animation-iteration-count: 1 !important;
         }
       }

       @media (forced-colors: active) {
         :root {
           --bg: Canvas;
           --panel: Canvas;
           --panel-solid: Canvas;
           --text: CanvasText;
           --muted: CanvasText;
           --line: CanvasText;
           --brand: Highlight;
           --brand-strong: Highlight;
           --danger: Mark;
           --danger-strong: Mark;
           --focus: Highlight;
         }

         .brand-mark,
         .button.primary,
         .button.danger {
           border: 1px solid ButtonText;
         }
       }
     </style>
   </head>
   <body>
     <a class="skip-link" href="#maincontent">Skip to main content</a>
     <div id="app"></div>

     <script>
       const state = {
         deleted: false,
         statusMessage: ""
       };

       const imageAlt =
         "Golden hour landscape with teal water, rugged cliffs, and a small sailboat crossing the bay";
       const imageSource =
         "data:image/svg+xml;utf8," +
         encodeURIComponent(`
           <svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 1600 1200" role="img" aria-label="${imageAlt}">
             <defs>
               <linearGradient id="sky" x1="0%" y1="0%" x2="0%" y2="100%">
                 <stop offset="0%" stop-color="#89c8ff"/>
                 <stop offset="52%" stop-color="#d8eeff"/>
                 <stop offset="100%" stop-color="#ffe7c4"/>
               </linearGradient>
               <linearGradient id="water" x1="0%" y1="0%" x2="100%" y2="100%">
                 <stop offset="0%" stop-color="#8dd7d0"/>
                 <stop offset="100%" stop-color="#3f8fb5"/>
               </linearGradient>
               <linearGradient id="cliff" x1="0%" y1="0%" x2="100%" y2="100%">
                 <stop offset="0%" stop-color="#5b667d"/>
                 <stop offset="100%" stop-color="#24324f"/>
               </linearGradient>
             </defs>
             <rect width="1600" height="1200" fill="url(#sky)"/>
             <rect y="620" width="1600" height="580" fill="url(#water)"/>
             <path d="M0 610c122-56 208-71 332-35 109 32 195 29 284-16 114-58 227-89 381-72 97 11 177 42 260 51 117 12 221-10 343-73v735H0Z" fill="#74c7c1" opacity=".66"/>
             <path d="M0 678c113-104 217-153 351-166 154-14 286 27 408 70 100 35 190 43 297 15 131-34 244-34 544 38V1200H0Z" fill="#4093b7" opacity=".42"/>
             <path d="M0 702c174-39 320-35 458 28 135 62 262 65 390 17 125-46 258-52 409-16 138 33 252 26 343-22V1200H0Z" fill="#1d6a8b" opacity=".4"/>
             <path d="M0 840c93-150 168-282 294-390 91-79 198-131 315-157 102-22 161-19 248 10-52 44-91 90-117 138 167-3 342 85 548 285V1200H0Z" fill="url(#cliff)"/>
             <path d="M1006 594c37-67 86-123 146-169 84-65 177-96 290-97-16 93-45 172-95 242 81-5 159 12 253 59l-233 136-482-171c40 0 81 0 121 0Z" fill="#3b4760"/>
             <path d="M1105 707l81-181 40 175-121 6Z" fill="#f7fbff"/>
             <path d="M1158 527l12 191" stroke="#25324c" stroke-width="8"/>
             <circle cx="230" cy="248" r="66" fill="#fff8d7" opacity=".72"/>
           </svg>
         `);

       function StatusRegion() {
         const isVisible = state.statusMessage ? "true" : "false";

         return `
           <div class="status-banner" data-visible="${isVisible}" role="status">
             ${state.statusMessage}
           </div>
         `;
       }

       function PageShell(children) {
         return `
           <header class="page-shell">
             <div class="topbar">
               <div class="brand" aria-label="Nova media library">
                 <span class="brand-mark" aria-hidden="true">N</span>
                 <span>Nova</span>
               </div>
               <div class="meta-chip" aria-label="Library sync status">
                 <span aria-hidden="true">●</span>
                 <span>Library synced</span>
               </div>
             </div>
           </header>
           <main id="maincontent" class="page-shell" tabindex="-1">
             ${StatusRegion()}
             ${children}
           </main>
         `;
       }

       function HeroSection() {
         return `
           <section class="hero" aria-labelledby="page-title">
             <p class="eyebrow">Image preview</p>
             <h1 id="page-title">Review a hero image before publishing</h1>
             <p class="hero-copy">
               Inspect the selected asset, check its metadata, and remove it from your library if it no
               longer belongs in your collection.
             </p>
           </section>
         `;
       }

       function ImagePreviewCard() {
         return `
           <article class="panel image-panel" aria-labelledby="image-title">
             <figure>
               <div class="image-frame">
                 <img src="${imageSource}" alt="${imageAlt}" />
               </div>
               <figcaption>
                 <div class="caption-main">
                   <h2 id="image-title">Sunset Coastline</h2>
                   <p>Uploaded by Maya Chen · 6048 × 4032 px · Edited 2 hours ago</p>
                 </div>
                 <div class="button-row">
                   <button type="button" class="button ghost" aria-label="Share Sunset Coastline image">
                     Share
                   </button>
                   <button
                     type="button"
                     class="button danger trigger"
                     id="open-delete-dialog"
                     aria-haspopup="dialog"
                     aria-controls="delete-dialog"
                   >
                     Delete image
                   </button>
                 </div>
               </figcaption>
             </figure>
           </article>
         `;
       }

       function DetailPanel() {
         return `
           <section class="panel detail-panel" aria-labelledby="details-title">
             <div class="detail-stack">
               <div>
                 <h2 id="details-title">Asset details</h2>
                 <p>Everything your team needs before approving, sharing, or deleting this file.</p>
               </div>
               <dl class="detail-list">
                 <dt>Collection</dt>
                 <dd>Campaign stills</dd>
                 <dt>Format</dt>
                 <dd>RAW + web export</dd>
                 <dt>Usage</dt>
                 <dd>Homepage hero, newsletter cover</dd>
                 <dt>Visibility</dt>
                 <dd>Shared with design and growth</dd>
               </dl>
               <div class="action-block">
                 <p class="helper-text">
                   Deleting removes this image from your library for everyone on the workspace.
                 </p>
               </div>
             </div>
           </section>
         `;
       }

       function EmptyState() {
         return `
           <section class="empty-state panel" id="empty-state" data-visible="true" aria-labelledby="empty-title">
             <div class="empty-state-card">
               <h2 id="empty-title">This image has been removed</h2>
               <p>
                 The asset is no longer available in your library. You can upload a new image when
                 you are ready.
               </p>
             </div>
           </section>
         `;
       }

       function ConfirmDeleteDialog() {
         return `
           <dialog id="delete-dialog" aria-labelledby="delete-dialog-title" aria-describedby="delete-dialog-body">
             <div class="dialog-card">
               <p class="dialog-eyebrow">Confirm deletion</p>
               <h2 id="delete-dialog-title">Delete this image from your library?</h2>
               <p id="delete-dialog-body">
                 This removes <strong>Sunset Coastline</strong> from shared access and cannot be undone.
               </p>
               <div class="dialog-actions">
                 <button type="button" class="button ghost" id="cancel-delete">Cancel</button>
                 <button type="button" class="button danger" id="confirm-delete">Delete image</button>
               </div>
             </div>
           </dialog>
         `;
       }

       function App() {
         const content = state.deleted
           ? EmptyState()
           : `
               <section class="preview-grid" aria-label="Image preview and details">
                 ${ImagePreviewCard()}
                 ${DetailPanel()}
               </section>
             `;

         return `
           ${PageShell(`
             ${HeroSection()}
             ${content}
           `)}
           ${ConfirmDeleteDialog()}
         `;
       }

       function bindEvents() {
         const dialog = document.getElementById("delete-dialog");
         const trigger = document.getElementById("open-delete-dialog");
         const cancelButton = document.getElementById("cancel-delete");
         const confirmButton = document.getElementById("confirm-delete");

         if (!dialog || !cancelButton || !confirmButton) {
           return;
         }

         if (trigger) {
           trigger.addEventListener("click", () => {
             if (typeof dialog.showModal === "function") {
               dialog.showModal();
             }
           });
         }

         cancelButton.addEventListener("click", () => {
           dialog.close("cancel");
         });

         dialog.addEventListener("click", (event) => {
           const bounds = dialog.getBoundingClientRect();
           const isInDialog =
             bounds.top <= event.clientY &&
             event.clientY <= bounds.top + bounds.height &&
             bounds.left <= event.clientX &&
             event.clientX <= bounds.left + bounds.width;

           if (!isInDialog) {
             dialog.close("cancel");
           }
         });

         confirmButton.addEventListener("click", () => {
           state.deleted = true;
           state.statusMessage = "The image was deleted from your library.";
           dialog.close("delete");
           render();

           const main = document.getElementById("maincontent");
           if (main) {
             main.focus();
           }
         });
       }

       function render() {
         document.getElementById("app").innerHTML = App();
         bindEvents();
       }

       render();
     </script>
   </body>
 </html>

')
